mapper.select:
SELECT s.student_id, s.name, s.class_name, sg.score_regular, sg.score_attendance, sg.score_homework, sg.score_experiment, sg.score_midterm, sg.score_final_exam, sg.score_resit, sg.score_total,
CASE -- If all scores are NULL, treat as not graded (9) WHEN sg.score_regular IS NULL AND sg.score_attendance IS NULL AND sg.score_homework IS NULL AND sg.score_experiment IS NULL AND sg.score_midterm IS NULL AND sg.score_final_exam IS NULL AND sg.score_resit IS NULL AND sg.score_total IS NULL THEN '9' -- If Resit exists and is pass (>=60), then Pass (2) WHEN sg.score_resit >= 60 THEN '2' -- If Total >= 60, then Pass (0) WHEN sg.score_total >= 60 THEN '0' -- Else Fail (1) ELSE '1' END as pass_status
FROM t_student_grade sg LEFT JOIN t_student s ON sg.student_id = s.student_id WHERE sg.course_id = #{courseId} AND sg.academic_year = #{academicYear} AND sg.semester = #{semester}
AND sg.class_seq = #{classSeq}

SELECT DISTINCT
    c.course_id,
    c.course_name,
    ta.class_seq
FROM t_teacher_assignment ta
LEFT JOIN t_course c ON ta.course_id = c.course_id
WHERE ta.teacher_id = #{teacherId}
  AND ta.academic_year = #{academicYear}
  AND ta.semester = #{semester}

SELECT grade_analysis
FROM t_teacher_assignment
WHERE course_id = #{courseId}
  AND teacher_id = #{teacherId}
  AND academic_year = #{academicYear}
  AND semester = #{semester}
  AND class_seq = #{classSeq}

mapper.update:
UPDATE t_teacher_assignment
SET grade_analysis = #{analysisContent}
WHERE course_id = #{courseId}
  AND teacher_id = #{teacherId}
  AND academic_year = #{academicYear}
  AND semester = #{semester}
  AND class_seq = #{classSeq}

mapper.select:
SELECT c.course_name, sg.academic_year, sg.semester, ROUND(AVG(IFNULL(sg.score_total, 0)), 1) as avg_score, MAX(IFNULL(sg.score_total, 0)) as max_score, MIN(IFNULL(sg.score_total, 0)) as min_score, /* Pass Rate Calculation: Count(>=60) / Count(*) */ ROUND( SUM(CASE WHEN IFNULL(sg.score_total, 0) >= 60 THEN 1 ELSE 0 END) * 100.0 / COUNT(*) , 1) as pass_rate, COUNT(DISTINCT s.class_name) as class_count
FROM t_student_grade sg LEFT JOIN t_course c ON sg.course_id = c.course_id LEFT JOIN t_student s ON sg.student_id = s.student_id /* Join teacher assignment to filter by teacher */ LEFT JOIN t_teacher_assignment ta ON sg.course_id = ta.course_id AND sg.academic_year = ta.academic_year AND sg.semester = ta.semester AND sg.class_seq = ta.class_seq WHERE 1=1
AND ta.teacher_id = #{teacherId}
AND c.course_name LIKE concat('%', #{courseName}, '%')
AND sg.academic_year = #{academicYear}
AND sg.semester = #{semester}
GROUP BY c.course_name, sg.academic_year, sg.semester ORDER BY sg.academic_year DESC, sg.semester DESC
